import sys
from elftools.elf.elffile import ELFFile
from capstone import *
from capstone.arm64 import *

path = sys.argv[1]
start = int(sys.argv[2], 16)
size = int(sys.argv[3], 16) if len(sys.argv) > 3 else 0x100

f = open(path, 'rb')
elf = ELFFile(f)

# map vaddr -> section data
secs = []
for s in elf.iter_sections():
    if s['sh_type'] == 'SHT_PROGBITS' and s['sh_flags'] & 0x2:  # ALLOC
        secs.append((s['sh_addr'], s['sh_addr'] + s['sh_size'], s.data(), s.name))

def read_at(addr, n):
    for lo, hi, data, name in secs:
        if lo <= addr and addr + n <= hi:
            return data[addr - lo: addr - lo + n]
    return None

def read_str(addr, maxlen=128):
    out = b''
    for i in range(maxlen):
        b = read_at(addr + i, 1)
        if b is None or b == b'\x00':
            break
        out += b
    try:
        t = out.decode('utf8')
        if all(32 <= ord(c) < 127 or c in '\t' for c in t):
            return t
    except Exception:
        pass
    return None

# symbol map for call targets
symtab = elf.get_section_by_name('.symtab') or elf.get_section_by_name('.dynsym')
syms = {}
if symtab:
    for sym in symtab.iter_symbols():
        if sym.name and sym['st_value']:
            syms.setdefault(sym['st_value'], sym.name)

def demangle(n):
    return n

code = read_at(start, size)
if code is None:
    print('address not in any PROGBITS section')
    sys.exit(1)

md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)
md.detail = True
adrp = {}
for ins in md.disasm(code, start):
    comment = ''
    if ins.mnemonic == 'adrp':
        reg = ins.op_str.split(',')[0].strip()
        imm = int(ins.op_str.split(',')[1].strip(), 16)
        adrp[reg] = imm
    elif ins.mnemonic in ('add', 'ldr', 'ldrsw') and len(ins.operands) >= 2:
        ops = ins.op_str.split(',')
        if len(ops) >= 2:
            src = ops[1].strip().split('[')[-1].strip()
            if src in adrp:
                base = adrp[src]
                if '#' in ops[-1] or (ins.mnemonic == 'add' and len(ops) == 3):
                    try:
                        imm_s = ops[-1].strip().lstrip('#').rstrip(']')
                        imm = int(imm_s, 16) if imm_s.startswith('0x') else int(imm_s)
                        tgt = base + imm
                        st = read_str(tgt)
                        if st:
                            comment = '  ; "%s"' % st[:100]
                        else:
                            comment = '  ; -> 0x%x' % tgt
                    except Exception:
                        pass
                elif ins.mnemonic.startswith('ldr'):
                    comment = '  ; -> 0x%x' % base
    if ins.mnemonic in ('bl', 'b'):
        try:
            tgt = int(ins.op_str.lstrip('#'), 16)
            if tgt in syms:
                comment = '  ; ' + syms[tgt][:110]
        except Exception:
            pass
    print(f"0x{ins.address:08x}:  {ins.mnemonic:<8} {ins.op_str}{comment}")

