import sys
from elftools.elf.elffile import ELFFile
from capstone import *
from capstone.arm64 import *

path = sys.argv[1]
target = int(sys.argv[2], 16)

f = open(path, 'rb')
elf = ELFFile(f)

code_secs = []
for s in elf.iter_sections():
    if s['sh_type'] == 'SHT_PROGBITS' and s['sh_flags'] & 0x4:  # EXECINSTR
        code_secs.append((s['sh_addr'], s.data()))

md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)
md.detail = True

for base, code in code_secs:
    adrp = {}
    prev_addr = None
    for ins in md.disasm(code, base):
        if ins.mnemonic == 'adrp':
            parts = ins.op_str.split(',')
            reg = parts[0].strip()
            adrp[reg] = (int(parts[1].strip().lstrip('#'), 16), ins.address)
        elif ins.mnemonic in ('add', 'ldr', 'ldrb', 'ldrh', 'ldrsw', 'str'):
            ops = ins.op_str.split(',')
            if len(ops) >= 2:
                src = ops[1].strip().lstrip('[').strip()
                if src in adrp:
                    pgbase, pa = adrp[src]
                    last = ops[-1].strip().lstrip('#').rstrip(']')
                    try:
                        imm = int(last, 16) if last.startswith('0x') else (int(last) if last.lstrip('-').isdigit() else None)
                    except Exception:
                        imm = None
                    if imm is not None and pgbase + imm == target:
                        print('xref @0x%x (%s %s)' % (ins.address, ins.mnemonic, ins.op_str))
        if ins.mnemonic not in ('adrp',):
            # clear regs that get overwritten? keep simple: expire after 8 instrs
            for r in list(adrp):
                if ins.address - adrp[r][1] > 0x40:
                    del adrp[r]

