            nm = dynsym.get_symbol(symidx).name
            if nm:
                got2sym[rel['r_offset']] = nm

# find PLT stubs: adrp x16, got; ldr x17,[x16,off]; br x16  OR via .plt section entries
# simpler: scan executable sections for 'adrp xN, page; ldr xN,[xN,#off]; ...' landing in got2sym
plt_targets = {}
md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)
md.detail = True
for s in elf.iter_sections():
    if s['sh_type'] == 'SHT_PROGBITS' and s['sh_flags'] & 0x4:
        base = s['sh_addr']; code = s.data()
        adrp = {}
        for ins in md.disasm(code, base):
            if ins.mnemonic == 'adrp':
                ops = ins.op_str.split(',')
                reg = ops[0].strip()
                adrp[reg] = (int(ops[1].strip().lstrip('#'), 16), ins.address)
            elif ins.mnemonic == 'ldr' and len(ins.op_str.split(',')) >= 2:
                ops = ins.op_str.split(',')
                src = ops[1].strip().lstrip('[').rstrip(']').strip()
                if src in adrp:
                    pg, _ = adrp[src]
                    last = ops[-1].strip().lstrip('#').rstrip(']')
                    try:
                        imm = int(last, 16) if last.startswith('0x') else int(last)
                    except Exception:
                        continue
                    tgt = pg + imm
                    if tgt in got2sym and got2sym[tgt] == sym_name:
                        plt_targets[ins.address] = tgt
            # expire
            for r in list(adrp):
                if ins.address - adrp[r][1] > 0x40:
                    del adrp[r]

if not plt_targets:
    print('no plt stub resolved for', sym_name)
    sys.exit(0)

# now find bl/b to these stub addresses
stub_addrs = set(plt_targets)
for s in elf.iter_sections():
    if s['sh_type'] == 'SHT_PROGBITS' and s['sh_flags'] & 0x4:
        base = s['sh_addr']; code = s.data()
        for ins in md.disasm(code, base):
            if ins.mnemonic in ('bl', 'b'):
                try:
                    t = int(ins.op_str.lstrip('#'), 16)
                except Exception:
                    continue
                if t in stub_addrs:
                    print('call @0x%x %s -> %s' % (ins.address, ins.mnemonic, sym_name))

